#requires -Version 5.1
[CmdletBinding()]
param([string]$PgBin='C:\Program Files\PostgreSQL\19\bin')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Read-Hidden([string]$Label){$s=Read-Host $Label -AsSecureString;try{if($s.Length -eq 0){throw 'Empty value.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Snapshot(){$op=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$oc=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$o=&$script:psql '-X' '-w' '-qAt' '-v' 'ON_ERROR_STOP=1' '-d' 'host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full' '-f' $script:sql;if($LASTEXITCODE -ne 0){throw 'Snapshot query failed.'};$z=@($o|Where-Object{$_-match'^\{'});if($z.Count -ne 1){throw 'Expected one snapshot record.'};$z[0]|ConvertFrom-Json}finally{if($null -eq $op){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$op};if($null -eq $oc){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oc}}}
function Request([Net.Http.HttpMethod]$Method,[string]$Path,[string]$ApiKey,[string]$Bearer,[object]$Body){$q=[Net.Http.HttpRequestMessage]::new($Method,$Path);try{$q.Headers.Add('apikey',$ApiKey);$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$Bearer);if($null-ne$Body){$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json $Body -Compress),[Text.Encoding]::UTF8,'application/json')};$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
$client=$handler=$publishable=$adminKey=$newPassword=$confirmPassword=$dbPassword=$approval=$null;$stage='initialization';$writeStarted=$false
try{
 $sql=Join-Path $PSScriptRoot 'snapshot_staging_agent_a_password_reset.sql';$cert=Join-Path $HOME 'Downloads\prod-ca-2021.crt';foreach($p in @($sql,$cert)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw 'Required local input missing.'}}
 $psql=(Resolve-Path (Join-Path $PgBin 'psql.exe')).Path;if((&$psql --version)-notmatch'PostgreSQL\)\s+19(?:\.\d+)?(?:\s|$)'){throw 'PostgreSQL 19 required.'};$ca=(Resolve-Path $cert).Path
 $publishable=(Read-Hidden 'Staging default publishable key').Trim();$adminKey=(Read-Hidden 'Staging Auth admin secret key').Trim();$newPassword=Read-Hidden 'New Agent A password';$confirmPassword=Read-Hidden 'Confirm new Agent A password';$dbPassword=Read-Hidden 'Staging PostgreSQL password'
 if($publishable-cnotmatch'^sb_publishable_[A-Za-z0-9_-]+$'-or$adminKey.Length-lt20){throw 'Invalid API credential format.'};if($newPassword-cne$confirmPassword-or$newPassword.Length-lt20-or$newPassword-cnotmatch'[A-Z]'-or$newPassword-cnotmatch'[a-z]'-or$newPassword-cnotmatch'[0-9]'-or$newPassword-cnotmatch'[^A-Za-z0-9]'){throw 'New password confirmation or strength guard failed.'};$confirmPassword=$null
 $stage='baseline';$before=Snapshot;if(-not[bool]$before.all_checks_pass){throw 'Auth baseline guard failed.'};Write-Output 'PASS six users five memberships and journal 21 baseline'
 Add-Type -AssemblyName System.Net.Http;$handler=[Net.Http.HttpClientHandler]::new();$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.Timeout=[TimeSpan]::FromSeconds(15)
 $approval=Read-Host 'Type STAGING-AGENT-A-PASSWORD-RESET-APPROVED';if($approval-cne'STAGING-AGENT-A-PASSWORD-RESET-APPROVED'){throw 'Password reset not locally confirmed.'}
 $stage='admin password reset';$writeStarted=$true;$x=Request ([Net.Http.HttpMethod]::Put) '/auth/v1/admin/users/0dae2b29-adaa-48b6-9a96-e9ac646b2a7a' $adminKey $adminKey @{password=$newPassword};if($x.Status -lt 200 -or $x.Status -ge 300){throw "Admin reset HTTP $($x.Status)"};$adminKey=$null
 $stage='Agent A login';$x=Request ([Net.Http.HttpMethod]::Post) '/auth/v1/token?grant_type=password' $publishable $publishable @{email='agent-a@reivro.invalid';password=$newPassword};if($x.Status -lt 200 -or $x.Status -ge 300){throw "Login HTTP $($x.Status)"};$login=$x.Body|ConvertFrom-Json;if([guid]$login.user.id -ne [guid]'0dae2b29-adaa-48b6-9a96-e9ac646b2a7a' -or [string]$login.user.email -cne 'agent-a@reivro.invalid'){throw 'Login returned an unexpected identity.'};$publishable=$newPassword=$login=$null;Write-Output 'PASS Agent A login after password reset'
 $stage='postcheck';$after=Snapshot;if(-not [bool]$after.all_checks_pass -or $after.other_users_hash -cne $before.other_users_hash -or $after.target_stable_hash -cne $before.target_stable_hash -or $after.protected_hash -cne $before.protected_hash -or [int]$after.users_count -ne 6 -or [int]$after.memberships_count -ne 5 -or [int]$after.journal_count -ne 21 -or [int]$after.journal_sequence -ne 21 -or -not [bool]$after.sequence_called){throw 'Post-reset Auth or protected baseline changed unexpectedly.'}
 Write-Output 'PASS UUID membership contracts submissions runs and journal preserved';Write-Output 'PASS other Auth accounts unchanged';Write-Output 'AGENT_A_PASSWORD_RESET_AND_LOGIN_PASS'
}catch{[Console]::Error.WriteLine("FAIL $stage");if($writeStarted){[Console]::Error.WriteLine('DO NOT RETRY. Run read-only reconciliation and test the intended password once.')}exit 1}finally{$publishable=$adminKey=$newPassword=$confirmPassword=$dbPassword=$approval=$login=$x=$null;Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
